// Byte positions accepted by the PHP mbstring encodings used by Laravel.
pub(super) fn big5(lead: u8, trail: u8) -> bool {
    match lead {
        0xa1 => matches!(trail, 0x40..=0x59 | 0x5b..=0x7e | 0xa1..=0xc2 | 0xc4 | 0xc6..=0xfd),
        0xa2 => matches!(trail, 0x41..=0x7e | 0xa1..=0xcb | 0xcd | 0xcf..=0xfe),
        0xa3 => matches!(trail, 0x40..=0x7e | 0xa1..=0xbf),
        0xa4..=0xc6 | 0xc9..=0xf9 => matches!(trail, 0x40..=0x7e | 0xa1..=0xfe),
        0xc7 => matches!(trail, 0x40..=0x7e | 0xa1..=0xfc),
        _ => false,
    }
}

pub(super) fn cp950(lead: u8, trail: u8) -> bool {
    matches!(lead, 0x81..=0xfe)
        && (matches!(trail, 0x40..=0x7e)
            || matches!(trail, 0xa1..=0xfe) && (lead != 0xa3 || trail <= 0xbf))
}

pub(super) fn euc_kr(lead: u8, trail: u8) -> bool {
    match lead {
        0xa1 | 0xa3..=0xa4 | 0xa9 | 0xb0..=0xc8 | 0xca..=0xfd => matches!(trail, 0xa1..=0xfe),
        0xa2 => matches!(trail, 0xa1..=0xe7),
        0xa5 => matches!(trail, 0xa1..=0xaa | 0xb0..=0xb9 | 0xc1..=0xd8 | 0xe1..=0xf8),
        0xa6 => matches!(trail, 0xa1..=0xe4),
        0xa7 => matches!(trail, 0xa1..=0xef),
        0xa8 => matches!(trail, 0xa1..=0xa4 | 0xa6 | 0xa8..=0xaf | 0xb1..=0xfe),
        0xaa => matches!(trail, 0xa1..=0xf3),
        0xab => matches!(trail, 0xa1..=0xf6),
        0xac => matches!(trail, 0xa1..=0xc1 | 0xd1..=0xf1),
        _ => false,
    }
}

pub(super) fn uhc(lead: u8, trail: u8) -> bool {
    match lead {
        0x81..=0xa0 => matches!(trail, 0x41..=0x5a | 0x61..=0x7a | 0x81..=0xfe),
        0xa1..=0xc5 => {
            matches!(trail, 0x41..=0x5a | 0x61..=0x7a | 0x81..=0xa0) || euc_kr(lead, trail)
        }
        0xc6 => matches!(trail, 0x41..=0x52) || euc_kr(lead, trail),
        _ => euc_kr(lead, trail),
    }
}
